.os-copy-control { flex: 0 0 auto; align-self: stretch; display: inline-flex; position: relative; }
.os-copy-button { border-left: 1px solid var(--foreground); background: var(--background); min-width: 48px; min-height: 48px; color: var(--foreground); justify-content: center; align-items: center; gap: 8px; padding: 12px; display: inline-flex; }
.os-copy-button:hover { background: var(--foreground); color: var(--background); }
