  .article-code-block-copy.os-copy-labelled { min-height: 40px; }
}
.os-copy-error { z-index: 1; border: 1px solid var(--foreground); background: var(--background); width: 240px; padding: 12px; position: absolute; top: 100%; right: 0px; }
.os-unavailable { border: 1px solid var(--foreground); justify-items: start; gap: 16px; padding: 32px 24px; display: grid; }
.os-unavailable a { text-underline-offset: 4px; text-decoration: underline; }
