.os-readme .readme-table { max-width: 100%; overflow-x: auto; }
.os-readme table { border-collapse: collapse; width: 100%; }
.os-readme th, .os-readme td { padding: 12px var(--space-cell); border: 1px solid var(--foreground); text-align: left; vertical-align: top; min-width: 128px; }
.os-readme th { font-weight: 600; }
.os-readme details { border: 1px solid var(--foreground); padding: 16px; }
